class CacheNode {
  constructor(name) {
    this.name = name;
    this.storage = new Map();
  }

  set(key, value) {
    this.storage.set(key, value);
  }

  get(key) {
    return this.storage.get(key);
  }
}

class DistributedCache {
  constructor(nodes) {
    this.nodes = nodes;
  }

  getNode(key) {
    const index = key.length % this.nodes.length;

    return this.nodes[index];
  }

  set(key, value) {
    const node = this.getNode(key);

    node.set(key, value);
  }

  get(key) {
    const node = this.getNode(key);

    return node.get(key);
  }
}

const cache = new DistributedCache([
  new CacheNode('Node-A'),
  new CacheNode('Node-B')
]);

cache.set('user:1', 'Nacho');

console.log(cache.get('user:1'));

class LoadBalancer {
  constructor(servers) {
    this.servers = servers;
    this.current = 0;
  }

  getServer() {
    const server = this.servers[this.current];

    this.current = (this.current + 1) % this.servers.length;

    return server;
  }
}

