});

class TokenBucket {
  constructor(capacity, refillRate) {
    this.capacity = capacity;
    this.tokens = capacity;
    this.refillRate = refillRate;

    setInterval(() => {
      this.tokens = Math.min(
        this.capacity,
        this.tokens + this.refillRate
      );
    }, 1000);
  }

  consume() {
    if (this.tokens <= 0) {
      console.log('Rate limit exceeded');

      return false;
    }

    this.tokens--;

    console.log('Request accepted');

    return true;
  }
}

const limiter = new TokenBucket(5, 1);

limiter.consume();

class LockManager {
  constructor() {
    this.locks = new Set();
  }

  acquire(resource) {
    if (this.locks.has(resource)) {
      console.log('Resource is locked');

      return false;
    }

    this.locks.add(resource);

    console.log(`Lock acquired for ${resource}`);

    return true;
  }

  release(resource) {
    this.locks.delete(resource);

    console.log(`Lock released for ${resource}`);
  }
}

const manager = new LockManager();

manager.acquire('payment-service');
manager.release('payment-service');

class StreamProcessor {
  constructor() {
    this.handlers = [];
  }

  use(handler) {
    this.handlers.push(handler);
  }

  process(event) {
    return this.handlers.reduce((current, handler) => {
      return handler(current);
    }, event);
  }
}

const processor = new StreamProcessor();

processor.use((event) => {
  return {
    ...event,
    processed: true
  };
});

console.log(processor.process({
  type: 'USER_LOGIN'
}));

class AuthProvider {
  constructor() {
    this.tokens = new Map();
  }

  generateToken(userId) {
    const token = `${userId}-${Date.now()}`;

    this.tokens.set(token, userId);

    return token;
  }

  validate(token) {
    return this.tokens.has(token);
  }
}

const auth = new AuthProvider();

const token = auth.generateToken('user-1');

console.log(auth.validate(token));
